</div>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<!-- ==========================================
     SECTION 2: PROFORMA INVOICE + META DETAILS
     ========================================== -->

<table style="
    width: 100%;
    border-collapse: collapse;
    border: 1.5px solid #1c3f60;
    font-family: Arial, Helvetica, sans-serif;
    margin-top: 0;
">

    <!-- PI TITLE -->
    <tr>
        <td colspan="3" style="
            padding: 7px 10px;
            text-align: center;
            border-bottom: 1px solid #1c3f60;
            color: #11466a;
            font-size: 14px;
            font-weight: bold;
            letter-spacing: 0.5px;
        ">
            PROFORMA INVOICE
        </td>
    </tr>

    <!-- DOCUMENT DETAILS -->
    <tr>

        <!-- PI NUMBER + MADE BY -->
        <td style="
            width: 35%;
            padding: 7px 10px;
            vertical-align: top;
            border-right: 1px solid #c9d6e0;
            font-size: 9px;
        ">
            <b>Proforma Invoice No. :</b>
            <br>
            {{ doc.name }}

            <div style="margin-top: 6px;">
                <b>Made By :</b>
                {{ doc.sales_person_name or frappe.db.get_value("User", doc.owner, "full_name") or "-" }}
            </div>
        </td>

        <!-- DATE -->
        <td style="
            width: 25%;
            padding: 7px 10px;
            vertical-align: top;
            border-right: 1px solid #c9d6e0;
            font-size: 9px;
        ">
            <b>Date :</b>
            <br>
            {{ frappe.utils.formatdate(doc.date, "dd-MM-yyyy") if doc.date else "" }}
        </td>

        <!-- DOCUMENT INFORMATION -->
        <td style="
            width: 40%;
            padding: 7px 10px;
            vertical-align: top;
            font-size: 9px;
            line-height: 1.5;
        ">
            <div>
                <b>Doc No. :</b>
                {{ doc.document_no or "-" }}
            </div>

            <div>
                <b>Rev No. :</b>
                {{ doc.rev_no or "-" }}
            </div>

            <div>
                <b>Updated :</b>
                {{ frappe.utils.formatdate(doc.modified, "dd-MM-yyyy") if doc.modified else "" }}
            </div>
        </td>

    </tr>

</table>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<!-- =========================================================
     SECTION 3 + SECTION 4  |  SINGLE TABLE (100 equal columns)

     BUYER : 45%   LABEL : 25%   VALUE : 30%
     ITEM  : 4 + 27 + 7 + 9 + 6 + 6 + 10 + 10 + 10 + 11 = 100

     FIX: header <th> now has background + color directly on it,
     so the text stays WHITE in PDF (wkhtmltopdf) also.
     ========================================================= -->

<style>
    .item-head th {
        background-color: #11466a !important;
        color: #ffffff !important;
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
    .item-head th span {
        color: #ffffff !important;
    }
</style>


<table style="
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    font-family: Arial, Helvetica, sans-serif;
    font-size: 9px;
    page-break-inside: auto;
    break-inside: auto;
">

    <colgroup>
        {% for i in range(100) %}
        <col style="width: 1%;">
        {% endfor %}
    </colgroup>


    <!-- ================= BUYER + DELIVERY NOTE ================= -->

    <tr>

        <td colspan="45" rowspan="5" style="
            padding: 7px 9px;
            vertical-align: top;
            border-left: 1.5px solid #1c3f60;
            border-right: 1px solid #999;
            border-top: 1.5px solid #1c3f60;
            border-bottom: 1.5px solid #1c3f60;
        ">

            <div style="font-size: 10px; font-weight: bold; color: #11466a; margin-bottom: 4px;">
                BUYER
            </div>

            <div style="font-size: 11px; font-weight: bold; line-height: 1.2; margin-bottom: 3px;">
                {{ doc.buyer or doc.customer }}
            </div>

            <div>
                <b>Name:</b>
                {{ doc.buyer_name or doc.buyer or doc.customer }}
            </div>

            <div style="margin-top: 4px; color: #444; line-height: 1.3;">
                <b>Address:</b>
                {{ doc.address or doc.consignee_address or "" }}
            </div>

            {% if doc.customer_phone_no %}
            <div style="margin-top: 2px;">
                <b>Phone:</b>
                {{ doc.customer_phone_no }}
            </div>
            {% endif %}

            {% if doc.buyers_email %}
            <div style="margin-top: 2px;">
                <b>Email:</b>
                {{ doc.buyers_email }}
            </div>
            {% endif %}

            {% if doc.consignee_gstin %}
            <div style="margin-top: 2px;">
                <b>GSTIN:</b>
                {{ doc.consignee_gstin }}
            </div>
            {% endif %}

        </td>

        <td colspan="25" style="
            padding: 6px 8px;
            font-weight: bold;
            background: #fafafa;
            border-right: 1px solid #999;
            border-top: 1.5px solid #1c3f60;
            border-bottom: 1px solid #999;
        ">
            Delivery Note
        </td>

        <td colspan="30" style="
            padding: 6px 8px;
            border-right: 1.5px solid #1c3f60;
            border-top: 1.5px solid #1c3f60;
            border-bottom: 1px solid #999;
        ">
            {{ doc.delivery_note or "NA" }}
        </td>

    </tr>


    <!-- ================= SUPPLIER'S REF. ================= -->

    <tr>
        <td colspan="25" style="
            padding: 6px 8px;
            font-weight: bold;
            background: #fafafa;
            border-right: 1px solid #999;
            border-bottom: 1px solid #999;
        ">
            Supplier's Ref.
        </td>

        <td colspan="30" style="
            padding: 6px 8px;
            border-right: 1.5px solid #1c3f60;
            border-bottom: 1px solid #999;
        ">
            {{ doc.suppliers_ref or "NA" }}
        </td>
    </tr>


    <!-- ================= OTHER REFERENCE(S) ================= -->

    <tr>
        <td colspan="25" style="
            padding: 6px 8px;
            font-weight: bold;
            background: #fafafa;
            border-right: 1px solid #999;
            border-bottom: 1px solid #999;
        ">
            Other Reference(s)
        </td>

        <td colspan="30" style="
            padding: 6px 8px;
            border-right: 1.5px solid #1c3f60;
            border-bottom: 1px solid #999;
        ">
            {{ doc.other_references or "NA" }}
        </td>
    </tr>


    <!-- ================= BUYER'S ORDER NO. ================= -->

    <tr>
        <td colspan="25" style="
            padding: 6px 8px;
            font-weight: bold;
            background: #fafafa;
            border-right: 1px solid #999;
            border-bottom: 1px solid #999;
        ">
            Buyer's Order No.
        </td>

        <td colspan="30" style="
            padding: 6px 8px;
            border-right: 1.5px solid #1c3f60;
            border-bottom: 1px solid #999;
        ">
            {{ doc.buyers_order_no or "NA" }}
        </td>
    </tr>


    <!-- ================= BUYER'S ORDER DATE ================= -->

    <tr>
        <td colspan="25" style="
            padding: 6px 8px;
            font-weight: bold;
            background: #fafafa;
            border-right: 1px solid #999;
            border-bottom: 1px solid #999;
        ">
            Buyer's Order Date
        </td>

        <td colspan="30" style="
            padding: 6px 8px;
            border-right: 1.5px solid #1c3f60;
            border-bottom: 1px solid #999;
        ">
            {{ frappe.utils.formatdate(
                doc.buyers_order_date,
                "dd-MM-yyyy"
            ) if doc.buyers_order_date else "NA" }}
        </td>
    </tr>


    <!-- ================= CONSIGNEE + DELIVERY DATE ================= -->

    <tr>

        <td colspan="45" rowspan="4" style="
            padding: 7px 9px;
            vertical-align: top;
            border-left: 1.5px solid #1c3f60;
            border-right: 1px solid #999;
            border-bottom: 1.5px solid #1c3f60;
        ">

            <div style="font-size: 10px; font-weight: bold; color: #11466a; margin-bottom: 4px;">
                CONSIGNEE
            </div>

            <div style="font-size: 11px; font-weight: bold; line-height: 1.2; margin-bottom: 3px;">
                {{ doc.customer }}
            </div>

            <div>
                <b>Name:</b>
                {{ doc.customer_name or doc.customer }}
            </div>

            <div style="margin-top: 4px; color: #444; line-height: 1.3;">
                <b>Address:</b>
                {{ doc.consignee_address or "" }}
            </div>

            {% if doc.customer_phone_no %}
            <div style="margin-top: 2px;">
                <b>Phone:</b>
                {{ doc.customer_phone_no }}
            </div>
            {% endif %}

            {% if doc.customer_email %}
            <div style="margin-top: 2px;">
                <b>Email:</b>
                {{ doc.customer_email }}
            </div>
            {% endif %}

            {% if doc.consignee_gstin %}
            <div style="margin-top: 2px;">
                <b>GSTIN:</b>
                {{ doc.consignee_gstin }}
            </div>
            {% endif %}

        </td>

        <td colspan="25" style="
            padding: 6px 8px;
            font-weight: bold;
            background: #fafafa;
            border-right: 1px solid #999;
            border-bottom: 1px solid #999;
        ">
            Delivery Date
        </td>

        <td colspan="30" style="
            padding: 6px 8px;
            border-right: 1.5px solid #1c3f60;
            border-bottom: 1px solid #999;
        ">
            {{ doc.delivery_date or "NA" }}
        </td>

    </tr>


    <!-- ================= DISPATCHED THROUGH ================= -->

    <tr>
        <td colspan="25" style="
            padding: 6px 8px;
            font-weight: bold;
            background: #fafafa;
            border-right: 1px solid #999;
            border-bottom: 1px solid #999;
        ">
            Dispatched Through
        </td>

        <td colspan="30" style="
            padding: 6px 8px;
            border-right: 1.5px solid #1c3f60;
            border-bottom: 1px solid #999;
        ">
            {{ doc.dispatched_through or "NA" }}
        </td>
    </tr>


    <!-- ================= FREIGHT TERMS ================= -->

    <tr>
        <td colspan="25" style="
            padding: 6px 8px;
            font-weight: bold;
            background: #fafafa;
            border-right: 1px solid #999;
            border-bottom: 1px solid #999;
        ">
            Freight Terms
        </td>

        <td colspan="30" style="
            padding: 6px 8px;
            border-right: 1.5px solid #1c3f60;
            border-bottom: 1px solid #999;
        ">
            {{ doc.freight_terms or "NA" }}
        </td>
    </tr>


    <!-- ================= TERMS OF PAYMENT ================= -->

    <tr>
        <td colspan="25" style="
            padding: 6px 8px;
            font-weight: bold;
            background: #fafafa;
            border-right: 1px solid #999;
            border-bottom: 1.5px solid #1c3f60;
        ">
            Terms of Payment
        </td>

        <td colspan="30" style="
            padding: 6px 8px;
            border-right: 1.5px solid #1c3f60;
            border-bottom: 1.5px solid #1c3f60;
        ">
            {{ doc.modeterms_of_payment or "NA" }}
        </td>
    </tr>


    <!-- =====================================================
         ITEM TABLE HEADER  (FIXED: white text on every <th>)
         ===================================================== -->

    <tr class="item-head" style="page-break-inside: avoid; break-inside: avoid;">

        <th colspan="4" style="
            padding: 6px 3px;
            border: 1px solid #1c3f60;
            text-align: center;
            vertical-align: middle;
            background: #11466a;
            color: #ffffff !important;
        "><span style="color:#ffffff;">Sr.</span></th>

        <th colspan="27" style="
            padding: 6px 4px;
            border: 1px solid #1c3f60;
            text-align: left;
            vertical-align: middle;
            background: #11466a;
            color: #ffffff !important;
        "><span style="color:#ffffff;">Item</span></th>

        <th colspan="7" style="
            padding: 6px 3px;
            border: 1px solid #1c3f60;
            text-align: center;
            vertical-align: middle;
            background: #11466a;
            color: #ffffff !important;
        "><span style="color:#ffffff;">Warranty</span></th>

        <th colspan="9" style="
            padding: 6px 3px;
            border: 1px solid #1c3f60;
            text-align: center;
            vertical-align: middle;
            background: #11466a;
            color: #ffffff !important;
        "><span style="color:#ffffff;">HSN Code</span></th>

        <th colspan="6" style="
            padding: 6px 3px;
            border: 1px solid #1c3f60;
            text-align: center;
            vertical-align: middle;
            background: #11466a;
            color: #ffffff !important;
        "><span style="color:#ffffff;">Qty</span></th>

        <th colspan="6" style="
            padding: 6px 3px;
            border: 1px solid #1c3f60;
            text-align: center;
            vertical-align: middle;
            background: #11466a;
            color: #ffffff !important;
        "><span style="color:#ffffff;">UOM</span></th>

        <th colspan="10" style="
            padding: 6px 3px;
            border: 1px solid #1c3f60;
            text-align: right;
            vertical-align: middle;
            background: #11466a;
            color: #ffffff !important;
        "><span style="color:#ffffff;">Rate</span></th>

        <th colspan="10" style="
            padding: 6px 3px;
            border: 1px solid #1c3f60;
            text-align: center;
            vertical-align: middle;
            background: #11466a;
            color: #ffffff !important;
        "><span style="color:#ffffff;">GST</span></th>

        <th colspan="10" style="
            padding: 6px 3px;
            border: 1px solid #1c3f60;
            text-align: right;
            vertical-align: middle;
            background: #11466a;
            color: #ffffff !important;
        "><span style="color:#ffffff;">Amount</span></th>

        <th colspan="11" style="
            padding: 6px 3px;
            border: 1px solid #1c3f60;
            text-align: right;
            vertical-align: middle;
            background: #11466a;
            color: #ffffff !important;
        "><span style="color:#ffffff;">Total</span></th>

    </tr>


    <!-- =====================================================
         ITEM ROWS
         ===================================================== -->

    {% for row in doc.items %}

    {%- set row_amount = row.amount or 0 -%}

    {%- set row_gst =
        (row.custom_igst_amount or 0)
        + (row.custom_cgst_amount or 0)
        + (row.custom_sgst_amount or 0)
    -%}

    {%- set row_total = row_amount + row_gst -%}

    <tr style="page-break-inside: avoid; break-inside: avoid;">

        <!-- SR = 4% -->
        <td colspan="4" style="
            padding: 5px 3px;
            border: 1px solid #999;
            text-align: center;
            vertical-align: top;
        ">
            {{ loop.index }}
        </td>

        <!-- ITEM = 27% -->
        <td colspan="27" style="
            padding: 5px 4px;
            border: 1px solid #999;
            vertical-align: top;
            word-break: break-word;
            overflow-wrap: anywhere;
        ">

            <div style="font-weight: bold; color: #11466a; font-size: 9px; line-height: 1.2;">
                {{ row.item }}
            </div>

            <div style="font-weight: bold; color: #11466a; margin-top: 1px; line-height: 1.2;">
                {{ row.item_name }}
            </div>

            {% if row.description %}
            <div style="
                margin-top: 3px;
                font-size: 8px;
                line-height: 1.3;
                color: #444;
                white-space: pre-wrap;
                overflow-wrap: anywhere;
            ">
                {{ row.description }}
            </div>
            {% endif %}

        </td>

        <!-- WARRANTY = 7% -->
        <td colspan="7" style="
            padding: 5px 3px;
            border: 1px solid #999;
            text-align: center;
            vertical-align: top;
        ">
            {{ row.warranty_years or 0 }}
        </td>

        <!-- HSN = 9% -->
        <td colspan="9" style="
            padding: 5px 3px;
            border: 1px solid #999;
            text-align: center;
            vertical-align: top;
            word-break: break-word;
        ">
            {{ (row.gst_hsn_code or 0)|int }}
        </td>

        <!-- QTY = 6% -->
        <td colspan="6" style="
            padding: 5px 3px;
            border: 1px solid #999;
            text-align: center;
            vertical-align: top;
        ">
            {{ row.quantity or "" }}
        </td>

        <!-- UOM = 6% -->
        <td colspan="6" style="
            padding: 5px 3px;
            border: 1px solid #999;
            text-align: center;
            vertical-align: top;
        ">
            {{ row.uom or "" }}
        </td>

        <!-- RATE = 10% -->
        <td colspan="10" style="
            padding: 5px 3px;
            border: 1px solid #999;
            text-align: right;
            vertical-align: top;
            white-space: nowrap;
        ">
            ₹ {{ "{:,.2f}".format(row.rate or 0) }}
        </td>

        <!-- GST = 10% -->
        <td colspan="10" style="
            padding: 5px 3px;
            border: 1px solid #999;
            text-align: center;
            vertical-align: top;
            word-break: break-word;
        ">

            {% if row.custom_igst_amount %}

                <div>IGST {{ row.custom_igst_rate|round(2) }}%</div>

                <div style="margin-top: 4px;">
                    ₹ {{ "{:,.2f}".format(row.custom_igst_amount or 0) }}
                </div>

            {% elif row.custom_cgst_amount or row.custom_sgst_amount %}

                <div>CGST {{ row.custom_cgst_rate|round(2) }}%</div>

                <div>SGST {{ row.custom_sgst_rate|round(2) }}%</div>

                <div style="margin-top: 4px;">
                    ₹ {{ "{:,.2f}".format(
                        (row.custom_cgst_amount or 0)
                        + (row.custom_sgst_amount or 0)
                    ) }}
                </div>

            {% else %}

                -

            {% endif %}

        </td>

        <!-- AMOUNT = 10% -->
        <td colspan="10" style="
            padding: 5px 2px;
            border: 1px solid #999;
            text-align: right;
            vertical-align: top;
            white-space: normal;
            overflow-wrap: break-word;
            word-break: break-word;
            font-size: 8px;
        ">
            ₹ {{ "{:,.2f}".format(row_amount) }}
        </td>

        <!-- TOTAL = 11% -->
        <td colspan="11" style="
            padding: 5px 3px;
            border: 1px solid #999;
            text-align: right;
            vertical-align: top;
            font-weight: bold;
            white-space: nowrap;
        ">
            ₹ {{ "{:,.2f}".format(row_total) }}
        </td>

    </tr>

    {% endfor %}

</table>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": ""}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": ""}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<!-- =========================================================
     SECTION 5: AMOUNT IN WORDS + BANK DETAILS + TOTALS
     ========================================================= -->

{%- set subtotal = (doc.items | sum(attribute="amount")) or 0 -%}
{%- set cgst_total = (doc.items | sum(attribute="custom_cgst_amount")) or 0 -%}
{%- set sgst_total = (doc.items | sum(attribute="custom_sgst_amount")) or 0 -%}
{%- set igst_total = (doc.items | sum(attribute="custom_igst_amount")) or 0 -%}
{%- set grand_total = doc.total_with_gst or doc.total or 0 -%}
{%- set amount_in_words = frappe.utils.money_in_words(grand_total, "INR") -%}


<table style="
    width: 100%;
    border-collapse: collapse;
    font-family: Arial, Helvetica, sans-serif;
    margin-top: 8px;
    page-break-inside: avoid;
    break-inside: avoid;
">

    <tr>

        <!-- =================================================
             LEFT SIDE
             ================================================= -->

        <td style="
            width: 55%;
            vertical-align: top;
            padding: 0 8px 0 0;
        ">

            <!-- AMOUNT IN WORDS -->

            <div style="
                border: 1px solid #1c3f60;
                page-break-inside: avoid;
                break-inside: avoid;
            ">

                <div style="
                    background: #11466a;
                    color: #fff;
                    padding: 5px 7px;
                    font-size: 8px;
                    font-weight: bold;
                    text-transform: uppercase;
                ">
                    Total Amount (In Words)
                </div>

                <div style="
                    padding: 7px 8px;
                    font-size: 9px;
                    font-weight: bold;
                    text-transform: capitalize;
                    min-height: 28px;
                ">
                    {{ amount_in_words }}
                </div>

            </div>


            <!-- COMPANY BANK DETAILS -->

            <div style="
                border: 1px solid #1c3f60;
                margin-top: 8px;
                page-break-inside: avoid;
                break-inside: avoid;
            ">

                <div style="
                    background: #11466a;
                    color: white;
                    padding: 5px 7px;
                    font-size: 8px;
                    font-weight: bold;
                    text-transform: uppercase;
                ">
                    Company Bank Details
                </div>


                <table style="
                    width: 100%;
                    border-collapse: collapse;
                    font-size: 8px;
                ">

                    <tr>

                        <td style="
                            width: 50%;
                            padding: 5px 6px;
                            border: 1px solid #eee;
                        ">
                            <b>Bank :</b>
                            Bank of Baroda
                        </td>

                        <td style="
                            width: 50%;
                            padding: 5px 6px;
                            border: 1px solid #eee;
                        ">
                            <b>A/c Name :</b>
                            ENERTECH UPS PVT. LTD.
                        </td>

                    </tr>

                    <tr>

                        <td style="
                            padding: 5px 6px;
                            border: 1px solid #eee;
                        ">
                            <b>A/c No. :</b>
                            80120400000554
                        </td>

                        <td style="
                            padding: 5px 6px;
                            border: 1px solid #eee;
                        ">
                            <b>IFSC :</b>
                            BARB0VJPIRA
